class EightPuzzle:
    GOAL_STATE = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]
    BLANK = 0
    GRID_SIZE = 3
    DIRECTIONS = ('up', 'down', 'left', 'right')

    def __init__(self, initial_state):
        self._initial_state = initial_state
        self._goal_state = [row[:] for row in self.GOAL_STATE]

    @property
    def initial_state(self):
        return self._initial_state

    @initial_state.setter
    def initial_state(self, value):
        self._initial_state = value

    @property
    def goal_state(self):
        return self._goal_state

    @goal_state.setter
    def goal_state(self, value):
        self._goal_state = value

    def find_blank(self, state):
        for i in range(self.GRID_SIZE):
            for j in range(self.GRID_SIZE):
                if state[i][j] == self.BLANK:
                    return i, j
        raise ValueError("Blank tile not found in state")

    def _swap_tiles(self, new_state, i, j, ni, nj):
        new_state[i][j], new_state[ni][nj] = new_state[ni][nj], new_state[i][j]

    def move(self, state, direction):
        i, j = self.find_blank(state)
        new_state = self._copy_state(state)

        if direction == 'up':
            self._swap_tiles(new_state, i, j, i - 1, j)
        elif direction == 'down':
            self._swap_tiles(new_state, i, j, i + 1, j)
        elif direction == 'left':
            self._swap_tiles(new_state, i, j, i, j - 1)
        elif direction == 'right':
            self._swap_tiles(new_state, i, j, i, j + 1)

        return new_state

    def _copy_state(self, state):
        return [row[:] for row in state]

    def get_possible_moves(self, state):
        i, j = self.find_blank(state)
        moves = []

        if self._can_move_up(i):
            moves.append('up')
        if self._can_move_down(i):
            moves.append('down')
        if self._can_move_left(j):
            moves.append('left')
        if self._can_move_right(j):
            moves.append('right')

        return moves

    def _can_move_up(self, i):
        return i > 0

    def _can_move_down(self, i):
        return i < self.GRID_SIZE - 1

    def _can_move_left(self, j):
        return j > 0

    def _can_move_right(self, j):
        return j < self.GRID_SIZE - 1

    def solve(self):
        open_list = [(self.initial_state, [])]
        closed_list = []

        while open_list:
            current_state, path = open_list.pop(0)
            if self._is_goal_state(current_state):
                return path
            closed_list.append(current_state)

            for move in self.get_possible_moves(current_state):
                new_state = self.move(current_state, move)
                if self._is_not_in_closed_list(new_state, closed_list):
                    open_list.append((new_state, self._extend_path(path, move)))

        return None

    def _is_goal_state(self, state):
        return state == self.goal_state

    def _is_not_in_closed_list(self, state, closed_list):
        return state not in closed_list

    def _extend_path(self, path, move):
        return path + [move]
